function run(){const s=Application('Safari'),w=s.windows[0];if(w.id()!==1296||!w.currentTab.url().startsWith('http://127.0.0.1:4185/#document='))throw Error('Not owned QA window');const se=Application('System Events'),matches=se.processes.whose({bundleIdentifier:'com.apple.inputmethod.SCIM'})(),p=matches[0];if(!p)return JSON.stringify({inputMethodProcessFound:false,matchedBundleIdentifier:'com.apple.inputmethod.SCIM'});function read(e,depth){const v={};for(const [k,f] of [['role',()=>e.role()],['name',()=>e.name()],['description',()=>e.description()],['value',()=>e.value()],['position',()=>e.position()],['size',()=>e.size()]])try{v[k]=f()}catch{}if(depth>0)try{v.children=e.uiElements().slice(0,30).map(c=>read(c,depth-1))}catch{}return v}return JSON.stringify({windowId:w.id(),inputMethodProcessFound:true,windows:p.windows().slice(0,3).map(e=>read(e,5))})}
